ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| ImageFileName=/\\(vssadmin|wmic|bcdedit|wbadmin|powershell|pwsh)\.exe$/i
| case {
    ImageFileName=/\\vssadmin\.exe$/i AND CommandLine=/delete\s+(shadows|\/all)/i | SabotageTag := "vss_delete";
    ImageFileName=/\\wmic\.exe$/i AND CommandLine=/shadowcopy/i AND CommandLine=/delete/i | SabotageTag := "wmic_vss";
    ImageFileName=/\\bcdedit\.exe$/i AND CommandLine=/(recoveryenabled\s+no|bootstatuspolicy\s+ignoreallfailures)/i | SabotageTag := "bcd_recovery_off";
    ImageFileName=/\\wbadmin\.exe$/i AND CommandLine=/delete\s+(catalog|systemstatebackup)/i | SabotageTag := "wbadmin_delete";
    ImageFileName=/\\(powershell|pwsh)\.exe$/i AND CommandLine=/Win32_Shadowcopy/i | SabotageTag := "ps_vss";
    * | SabotageTag := "";
  }
| SabotageTag!=""
| bucket(field=@timestamp, span=5m, function=[collect([SabotageTag, CommandLine]), count(field=SabotageTag, distinct=true, as=distinct_actions), min(@timestamp, as=first_seen)])
| groupBy([aid, ComputerName, UserName, _bucket], function=[max(distinct_actions, as=actions), min(first_seen, as=first_seen), collect([SabotageTag, CommandLine])])
| actions >= 3
